#include <bits/stdc++.h>
using namespace std;

vector<int> decode(const string& s) {
    vector<int> result;

    for (size_t i = 0; i < s.size();) {
        unsigned char c = s[i];
        int cp;
        size_t len;

        if (c < 0x80) {
            cp = c;
            len = 1;
        } else if ((c & 0xE0) == 0xC0) {
            cp = c & 0x1F;
            len = 2;
        } else if ((c & 0xF0) == 0xE0) {
            cp = c & 0x0F;
            len = 3;
        } else {
            cp = c & 0x07;
            len = 4;
        }

        for (size_t j = 1; j < len && i + j < s.size(); ++j)
            cp = (cp << 6) | (static_cast<unsigned char>(s[i + j]) & 0x3F);

        i += len;

        if (cp >= 0x00E0 && cp <= 0x00E5) cp = 'a';
        else if (cp == 0x00E7) cp = 'c';
        else if (cp >= 0x00E8 && cp <= 0x00EB) cp = 'e';
        else if (cp >= 0x00EC && cp <= 0x00EF) cp = 'i';
        else if (cp == 0x00F1) cp = 'n';
        else if (cp >= 0x00F2 && cp <= 0x00F6) cp = 'o';
        else if (cp >= 0x00F9 && cp <= 0x00FC) cp = 'u';
        else if (cp == 0x00FD || cp == 0x00FF) cp = 'y';

        result.push_back(cp);
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string P, A;
    cin >> P >> A;

    map<int, int> count;
    for (int c : decode(P)) ++count[c];

    bool valid = true;
    for (int c : decode(A)) {
        if (c == '*') continue;
        if (--count[c] < 0) valid = false;
    }

    cout << (valid ? 'S' : 'N') << '\n';
    return 0;
}
